import { DOCUMENT } from "@angular/common";
import {
  afterRenderEffect,
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  input,
  linkedSignal,
  model,
  signal,
  untracked,
} from "@angular/core";
import { Router } from "@angular/router";
import { NgIcon } from "@ng-icons/core";
import { lucideCornerDownLeft, lucideSearch } from "@ng-icons/lucide";
import { paletteGroups, type PaletteOption } from "@/ui/layout/command-palette";
import type { Command } from "@/ui/layout/command-registry";
import type { NavConfig } from "@/ui/layout/nav";
import {
  KoDialog,
  KoDialogContent,
  KoDialogDescription,
  KoDialogTitle,
} from "@/ui/primitives/dialog.component";
import { cn } from "@/ui/utils";

let nextId = 0;

const itemClass =
  "flex h-10 cursor-pointer items-center gap-3 rounded-md px-2.5 text-sm text-foreground outline-none aria-selected:bg-secondary";
const groupClass = "px-1 py-1 text-xs text-muted-foreground";

/**
 * Search pages and actions, and run one. Focus stays in the search input (a combobox); the
 * arrow keys move the active option (`aria-activedescendant`), Enter runs it, and Escape, a
 * backdrop click or running an option closes the palette. `[(open)]` works both ways.
 */
@Component({
  selector: "ko-command-palette",
  imports: [NgIcon, KoDialog, KoDialogContent, KoDialogTitle, KoDialogDescription],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  templateUrl: "./command-palette.component.html",
})
export class KoCommandPalette {
  readonly open = model(false);
  readonly nav = input.required<NavConfig>();
  readonly commands = input<Command[]>([]);
  readonly placeholder = input("Search…");

  protected readonly searchIcon = lucideSearch;
  protected readonly enterIcon = lucideCornerDownLeft;
  protected readonly itemClass = itemClass;
  protected readonly id = `ko-command-palette-${nextId++}`;
  protected readonly listId = `${this.id}-list`;

  protected readonly query = signal("");
  protected readonly groups = computed(() =>
    paletteGroups(this.query(), this.nav(), this.commands()),
  );
  protected readonly options = computed(() => this.groups().flatMap((group) => group.options));
  /** The first option is active whenever the list changes, as in cmdk. */
  protected readonly active = linkedSignal({ source: this.options, computation: () => 0 });
  protected readonly activeId = computed(() =>
    this.options().length ? this.optionId(this.active()) : null,
  );

  private readonly router = inject(Router);
  private readonly document = inject(DOCUMENT);

  constructor() {
    effect(() => {
      if (!this.open()) untracked(() => this.query.set(""));
    });
    afterRenderEffect(() => {
      const id = this.activeId();
      if (id) this.document.getElementById(id)?.scrollIntoView?.({ block: "nearest" });
    });
  }

  protected optionId(index: number): string {
    return `${this.id}-option-${index}`;
  }

  protected headingId(index: number): string {
    return `${this.id}-group-${index}`;
  }

  protected groupClasses(index: number): string {
    return cn(groupClass, index > 0 && "mt-1 border-t border-border pt-2");
  }

  protected onInput(event: Event): void {
    this.query.set((event.target as HTMLInputElement).value);
  }

  protected onKeydown(event: KeyboardEvent): void {
    const count = this.options().length;
    if (event.isComposing) return;
    switch (event.key) {
      case "ArrowDown":
      case "ArrowUp": {
        event.preventDefault();
        if (!count) return;
        const step = event.key === "ArrowDown" ? 1 : -1;
        this.active.update((index) => (index + step + count) % count);
        return;
      }
      case "Home":
      case "End":
        if (!count) return;
        event.preventDefault();
        this.active.set(event.key === "Home" ? 0 : count - 1);
        return;
      case "Enter": {
        const option = this.options()[this.active()];
        if (!option) return;
        event.preventDefault();
        this.choose(option);
        return;
      }
    }
  }

  protected choose(option: PaletteOption): void {
    this.open.set(false);
    if (option.command) option.command.run();
    else if (option.to) void this.router.navigateByUrl(option.to);
  }
}

import type { Command } from "./command-registry";
import { matchesTokens, searchTokens } from "./command-search";
import { navItems, type NavConfig } from "./nav";

/** One row of the palette: a command to run, or a page to open. */
export type PaletteOption = {
  /** Unique within the list: `command-{id}` or `page-{to}`. */
  key: string;
  /** The position in the whole list, across groups: what the arrow keys move. */
  index: number;
  label: string;
  icon?: string;
  description?: string;
  command?: Command;
  to?: string;
};

export type PaletteGroup = { heading: string; options: PaletteOption[] };

/**
 * The palette's list for a query: the matching commands by group (in the order the groups
 * first appear), then the matching pages under "Pages", or "Navigate" while searching.
 * Commands match on label, group, description and keywords; pages on label and keywords.
 * Groups with no match are left out.
 */
export function paletteGroups(
  query: string,
  nav: NavConfig,
  commands: readonly Command[],
): PaletteGroup[] {
  const tokens = searchTokens(query);
  const byGroup = new Map<string, Command[]>();
  for (const command of commands) {
    const fields = {
      name: command.label,
      group: command.group,
      description: command.description ?? "",
      keywords: (command.keywords ?? []).join(" "),
    };
    if (!matchesTokens(tokens, fields)) continue;
    byGroup.set(command.group, [...(byGroup.get(command.group) ?? []), command]);
  }
  const pages = navItems(nav).filter((item) =>
    matchesTokens(tokens, { name: item.label, keywords: (item.keywords ?? []).join(" ") }),
  );

  let index = 0;
  const groups: PaletteGroup[] = [...byGroup].map(([heading, list]) => ({
    heading,
    options: list.map((command) => ({
      key: `command-${command.id}`,
      index: index++,
      label: command.label,
      icon: command.icon,
      description: command.description,
      command,
    })),
  }));
  if (pages.length) {
    groups.push({
      heading: tokens.length ? "Navigate" : "Pages",
      options: pages.map((item) => ({
        key: `page-${item.to}`,
        index: index++,
        label: item.label,
        icon: item.icon,
        to: item.to,
      })),
    });
  }
  return groups;
}

import { describe, expect, it } from "vitest";
import { paletteGroups } from "./command-palette";
import type { Command } from "./command-registry";
import type { NavConfig } from "./nav";

const run = () => undefined;
const nav: NavConfig = {
  primary: [
    { to: "/", label: "Overview", icon: "<svg/>", keywords: ["home"] },
    { to: "/grid", label: "Data grid", icon: "<svg/>" },
  ],
  secondary: [{ to: "/settings", label: "Settings", icon: "<svg/>", keywords: ["preferences"] }],
};
const commands: Command[] = [
  { id: "new", label: "New item", group: "Actions", run },
  { id: "out", label: "Sign out", group: "Account", description: "End the session", run },
  { id: "reset", label: "Reset settings", group: "Actions", run },
  { id: "theme", label: "Toggle theme", group: "Appearance", keywords: ["dark"], run },
];

const shape = (query: string) =>
  paletteGroups(query, nav, commands).map((group) => [
    group.heading,
    group.options.map((option) => option.label),
  ]);

describe("paletteGroups", () => {
  it("lists commands by group in first-seen order, then the pages under Pages", () => {
    expect(shape("")).toEqual([
      ["Actions", ["New item", "Reset settings"]],
      ["Account", ["Sign out"]],
      ["Appearance", ["Toggle theme"]],
      ["Pages", ["Overview", "Data grid", "Settings"]],
    ]);
  });

  it("numbers the options in display order", () => {
    const indexes = paletteGroups("", nav, commands).flatMap((group) =>
      group.options.map((option) => option.index),
    );
    expect(indexes).toEqual([0, 1, 2, 3, 4, 5, 6]);
  });

  it("matches commands on label, group, description and keywords", () => {
    expect(shape("session")).toEqual([["Account", ["Sign out"]]]);
    expect(shape("dark")).toEqual([["Appearance", ["Toggle theme"]]]);
    expect(shape("appearance")).toEqual([["Appearance", ["Toggle theme"]]]);
  });

  it("matches pages on label and keywords, under Navigate while searching", () => {
    expect(shape("prefer")).toEqual([["Navigate", ["Settings"]]]);
    expect(shape("sett")).toEqual([
      ["Actions", ["Reset settings"]],
      ["Navigate", ["Settings"]],
    ]);
  });

  it("drops empty groups", () => {
    expect(shape("zzz")).toEqual([]);
  });

  it("carries the command or the page target, and the icon", () => {
    const [actions, , , pages] = paletteGroups("", nav, commands);
    expect(actions.options[0].command?.id).toBe("new");
    expect(actions.options[0].to).toBeUndefined();
    expect(pages.options[2].to).toBe("/settings");
    expect(pages.options[2].icon).toBe("<svg/>");
    expect(pages.options[2].command).toBeUndefined();
  });
});

import {
  assertInInjectionContext,
  computed,
  DestroyRef,
  effect,
  inject,
  Injectable,
  isSignal,
  signal,
  type Signal,
} from "@angular/core";

/** Something the palette can run besides opening a page: "New item", "Sign out". */
export type Command = {
  id: string;
  label: string;
  /** The group heading it is listed under. */
  group: string;
  /** The SVG string of the icon, such as `lucidePlus` from `@ng-icons/lucide`. */
  icon?: string;
  description?: string;
  keywords?: readonly string[];
  run: () => void;
};

/** The commands the app shell's palette lists, by the owner that registered them. */
@Injectable({ providedIn: "root" })
export class KoCommandRegistry {
  private readonly owners = signal<ReadonlyMap<string, Command[]>>(new Map());

  /** Every registered command, in the order the owners first registered. */
  readonly commands: Signal<Command[]> = computed(() => [...this.owners().values()].flat());

  /** Sets the commands of `owner`, replacing what it registered before. */
  register(owner: string, commands: Command[]): void {
    this.owners.update((all) => new Map(all).set(owner, commands));
  }

  unregister(owner: string): void {
    this.owners.update((all) => {
      if (!all.has(owner)) return all;
      const next = new Map(all);
      next.delete(owner);
      return next;
    });
  }
}

let nextOwner = 0;

/**
 * Adds commands to the palette while the calling component (or service) lives. A signal is
 * followed: its current commands replace the previous ones. Call it in an injection context.
 */
export function injectCommands(commands: Command[] | Signal<Command[]>): void {
  assertInInjectionContext(injectCommands);
  const registry = inject(KoCommandRegistry);
  const owner = `ko-commands-${nextOwner++}`;
  if (isSignal(commands)) {
    effect(() => registry.register(owner, commands()));
  } else {
    registry.register(owner, commands);
  }
  inject(DestroyRef).onDestroy(() => registry.unregister(owner));
}

export function searchTokens(value: string): string[] {
  return value.trim().toLowerCase().split(/\s+/).filter(Boolean);
}

/**
 * Every token must appear in one of the fields. `field:value` restricts a token to one
 * field, so `tag:prod` only matches the `tag` field. Fields are compared lowercased.
 */
export function matchesTokens(tokens: string[], fields: Record<string, string>): boolean {
  return tokens.every((token) => {
    const separator = token.indexOf(":");
    if (separator > 0) {
      const field = token.slice(0, separator);
      const value = token.slice(separator + 1);
      if (value && fields[field] != null) return fields[field].toLowerCase().includes(value);
    }
    return Object.values(fields).some((value) => value.toLowerCase().includes(token));
  });
}

import { expect, it } from "vitest";
import { matchesTokens, searchTokens } from "./command-search";

it("splits a query into lowercased words", () => {
  expect(searchTokens("  New   Item ")).toEqual(["new", "item"]);
  expect(searchTokens("")).toEqual([]);
});

it("matches nothing but an empty query when there are no tokens", () => {
  expect(matchesTokens([], { name: "Overview" })).toBe(true);
  expect(matchesTokens(searchTokens("zzz"), { name: "Overview" })).toBe(false);
});

it("requires every token to appear in some field", () => {
  const fields = { name: "Overview", keywords: "home dashboard summary" };
  expect(matchesTokens(searchTokens("over"), fields)).toBe(true);
  expect(matchesTokens(searchTokens("dashboard"), fields)).toBe(true);
  expect(matchesTokens(searchTokens("dashboard over"), fields)).toBe(true);
  expect(matchesTokens(searchTokens("dashboard missing"), fields)).toBe(false);
});

it("restricts a `field:value` token to that field", () => {
  const fields = { name: "Overview", keywords: "dashboard" };
  expect(matchesTokens(searchTokens("name:view"), fields)).toBe(true);
  expect(matchesTokens(searchTokens("keywords:view"), fields)).toBe(false);
});

it("treats a token with an unknown field as plain text", () => {
  const fields = { name: "Overview", keywords: "dashboard" };
  // The colon is part of the text, so it cannot be mistaken for a field restriction.
  expect(matchesTokens(searchTokens("nope:dashboard"), fields)).toBe(false);
  expect(matchesTokens(searchTokens("nope:other"), fields)).toBe(false);
});
